package com.pandinila.broadband_management.service; import com.pandinila.broadband_management.entity.Customer; import com.pandinila.broadband_management.repository.CustomerRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class CustomerService { private final CustomerRepository repo; public CustomerService(CustomerRepository r){repo=r;} public List<Customer> all(){return repo.findAll();} public Customer one(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Customer not found: "+id));} public Customer save(Customer c){return repo.save(c);} public void delete(Long id){repo.delete(one(id));} }
